// ─── File: TrackerDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TrackerDemo {

    private static final Logger log = Logger.getLogger(TrackerDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Tracking transaction-search sprint at " + BANK_NAME);

        int totalTasks = 20;
        int sprintDays = 10;
        SprintTracker tracker = new SprintTracker(totalTasks, sprintDays);
        BurndownPolicy policy = new BurndownPolicy(2);

        // Simulate a sprint that starts fine then falls behind due to the audit dependency.
        int[] completedByDay = {2, 4, 5, 6, 7, 8, 9, 11, 14, 17};
        for (int day = 1; day <= sprintDays; day++) {
            tracker.record(new DayProgress(day, completedByDay[day - 1]));
            int actualRemaining = tracker.remainingTasks();
            int idealRemaining = tracker.idealRemaining(day);
            boolean atRisk = policy.isAtRisk(actualRemaining, idealRemaining);
            if (atRisk) {
                log.warning(() -> "Day " + tracker.lastDay() + ": AT RISK — behind by "
                        + (tracker.remainingTasks() - tracker.idealRemaining(tracker.lastDay()))
                        + " tasks. Communicate and re-scope now.");
            } else {
                log.info(() -> "Day " + tracker.lastDay() + ": on track, "
                        + tracker.remainingTasks() + " tasks remaining.");
            }
        }

        int finalRemaining = tracker.remainingTasks();
        if (finalRemaining > 0) {
            log.severe(() -> "Deadline missed with " + finalRemaining
                    + " tasks left — but it was flagged early, not at the end.");
        } else {
            log.info("Sprint completed on time.");
        }
    }
}

// ─── Would be in model/DayProgress.java in a real project ───
class DayProgress {
    private final int day;
    private final int cumulativeCompleted;

    DayProgress(int day, int cumulativeCompleted) {
        this.day = day;
        this.cumulativeCompleted = cumulativeCompleted;
    }

    int getDay() { return day; }
    int getCumulativeCompleted() { return cumulativeCompleted; }
}

// ─── Would be in tracker/SprintTracker.java in a real project ───
class SprintTracker {
    private static final Logger log = Logger.getLogger(SprintTracker.class.getName());
    private final int totalTasks;
    private final int sprintDays;
    private final List<DayProgress> history = new ArrayList<>();

    SprintTracker(int totalTasks, int sprintDays) {
        this.totalTasks = totalTasks;
        this.sprintDays = sprintDays;
    }

    void record(DayProgress progress) {
        history.add(progress);
        log.fine(() -> "Recorded day " + progress.getDay()
                + ", completed=" + progress.getCumulativeCompleted());
    }

    int lastDay() {
        return history.get(history.size() - 1).getDay();
    }

    int remainingTasks() {
        int done = history.get(history.size() - 1).getCumulativeCompleted();
        return totalTasks - done;
    }

    // Ideal remaining work on a given day assumes even progress across the sprint.
    int idealRemaining(int day) {
        double perDay = (double) totalTasks / sprintDays;
        int idealDone = (int) Math.round(perDay * day);
        return Math.max(0, totalTasks - idealDone);
    }
}

// ─── Would be in policy/BurndownPolicy.java in a real project ───
class BurndownPolicy {
    private final int atRiskThreshold;

    BurndownPolicy(int atRiskThreshold) {
        this.atRiskThreshold = atRiskThreshold;
    }

    boolean isAtRisk(int actualRemaining, int idealRemaining) {
        return (actualRemaining - idealRemaining) >= atRiskThreshold;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
